(()=>{const steps=[...document.querySelectorAll('.step')],next=document.querySelector('.primary'),back=document.createElement('button');back.className='secondary';back.textContent='Back';back.disabled=true;next.parentNode.prepend(back);let index=0;const render=()=>{steps.forEach((step,i)=>step.classList.toggle('active',i<=index));back.disabled=index===0;next.textContent=index===steps.length-1?'Finish demonstration':'Continue'};back.onclick=()=>{index=Math.max(0,index-1);render()};next.onclick=()=>{index=Math.min(steps.length-1,index+1);render()};document.querySelector('.proto-nav').onclick=e=>{if(e.target.matches('a')){e.preventDefault();index=Math.max(0,[...document.querySelectorAll('.proto-nav a')].indexOf(e.target));render()}};render()})();
